"use client";


import React, { useEffect, useState } from "react";
import { getCarrito } from "../Data/Cart"; // Asegúrate de que se importa correctamente

import styles from "../styles/NewCartModal.module.css"; // Estilos para el modal

interface Product {
  code: string;
  name: string;
  price: number;
}

interface NewCartModalProps {
  handleClose: () => void;
  products: Product[];
  handleDeleteProduct: (productCode: string) => void; // Esta es la propiedad que vamos a usar
}

const NewCartModal: React.FC<NewCartModalProps> = ({
  handleClose,
  products,
  handleDeleteProduct, // Desestructuramos la propiedad
}) => {
  // Estado para el carrito
  const [cartItems, setCartItems] = useState(getCarrito());

  // Efecto para actualizar el carrito cuando cambia
  useEffect(() => {
    setCartItems(getCarrito()); // Actualizar el estado con el carrito cada vez que el componente se renderice
  }, []); // Este efecto se ejecutará solo una vez cuando se monte el componente

  // Función para obtener el producto por su código
  const getProductByCode = (code: string) => {
    return products.find((product) => product.code === code);
  };

  // Calcular el total del carrito
  const calculateTotal = () => {
    return cartItems.reduce((total, item) => {
      const product = getProductByCode(item.code);
      if (product) {
        return total + product.price * item.quantity;
      }
      return total;
    }, 0);
  };

  return (
    <div className={styles.modal}>
      <div className={styles.modalContent}>
        <button onClick={handleClose} className={styles.closeButton}>
          X
        </button>
        <h2>Resumen del Carrito</h2>
        <div className={styles.cartItems}>
          {cartItems.length === 0 ? (
            <p>El carrito está vacío.</p>
          ) : (
            cartItems.map((item) => {
              const product = getProductByCode(item.code);
              return product ? (
                <div key={item.code} className={styles.cartItem}>
                  <p>
                    {product.name} - Cantidad: {item.quantity} - Precio: $
                    {product.price}
                  </p>
                  <button
                    onClick={() => handleDeleteProduct(item.code)} // Usamos handleDeleteProduct aquí
                    className={styles.removeButton}
                  >
                    Eliminar
                  </button>
                </div>
              ) : null;
            })
          )}
        </div>
        <h3>Total: ${calculateTotal()}</h3>
      </div>
    </div>
  );
};

export default NewCartModal;
